"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  CONCENTRATION_PATH,
  HEADLINE,
  MSFT_SENSITIVITY,
  PERIMETER_STACKS,
  POSITIVE_RAISE_SLICES,
  RAISE_ROWS,
  SHARE_LADDER_Q3,
  SOURCE_NOTE,
  SOURCES,
  YEAR_LABELS,
  companyShares,
  concentrationCurve,
  concentrationMetrics,
  fmtBn,
  fmtHhi,
  fmtPct,
  type CapexYearKey,
} from "@/data/ai-capex-spend-concentration-2026q3-data";

// viz-types: Lorenz area+line, ranked share bars, raise donut, path multi-line, perimeter bars, share-dollar scatter | layout: default

type ViewId = "ladder" | "path" | "raises" | "perimeters";

const TEAL = "#0d9488";
const AMBER = "#f59e0b";
const SKY = "#0ea5e9";
const VIOLET = "#8b5cf6";
const SLATE = "#64748b";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="flex flex-wrap gap-1">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "bg-slate-100 text-slate-700 hover:bg-slate-200"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function AiCapexSpendConcentration2026q3Dashboard() {
  const [view, setView] = useState<ViewId>("ladder");
  const [year, setYear] = useState<CapexYearKey>("2026-q3");
