                    type="monotone"
                    dataKey="top1Pct"
                    stroke={AMBER}
                    strokeWidth={2.5}
                    dot={{ r: 4 }}
                    name="top1Pct"
                  />
                  <Line
                    type="monotone"
                    dataKey="top3Pct"
                    stroke={TEAL}
                    strokeWidth={2.5}
                    dot={{ r: 4 }}
                    name="top3Pct"
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="HHI path"
            subtitle="Herfindahl???Hirschman index on Big-5 shares (higher = more concentrated)"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={CONCENTRATION_PATH}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 10 }} />
                  <YAxis tick={{ fontSize: 11 }} domain={[2000, 2600]} />
                  <Tooltip formatter={(v) => [fmtHhi(Number(v)), "HHI"]} />
                  <Area
                    type="monotone"
                    dataKey="hhi"
                    fill={VIOLET}
                    fillOpacity={0.2}
                    stroke={VIOLET}
                    strokeWidth={2}
                  />
                  <Line
                    type="monotone"
                    dataKey="hhi"
                    stroke={VIOLET}
                    strokeWidth={2}
                    dot={{ r: 4 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Stack size vs concentration"
            subtitle="Absolute dollars rose faster than equalisation ??? HHI stayed elevated"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={CONCENTRATION_PATH}
                  margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 10 }} />
                  <YAxis
                    yAxisId="left"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `$${v}B`}
                  />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                    domain={[20, 40]}
                  />
                  <Tooltip />
                  <Bar
                    yAxisId="left"
                    dataKey="totalBn"
                    fill={SKY}
                    fillOpacity={0.7}
                    name="Big-5 total"
                    radius={[4, 4, 0, 0]}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="top1Pct"
                    stroke={AMBER}
                    strokeWidth={2.5}
                    name="Top-1 %"
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Mid-Q3 ladder snapshot"
            subtitle="Fixed mid-Q3 ranks for quick reference"
          >
            <div className="overflow-x-auto">
              <table className="w-full min-w-[280px] text-left text-sm">
                <thead>
                  <tr className="border-b border-slate-200 text-xs uppercase text-slate-500">
                    <th className="py-2 pr-2">Company</th>
                    <th className="py-2 pr-2 text-right">$B</th>
                    <th className="py-2 pr-2 text-right">Share</th>
                    <th className="py-2 text-right">Cum.</th>
                  </tr>
                </thead>
                <tbody>
                  {SHARE_LADDER_Q3.map((r) => (
                    <tr key={r.company} className="border-b border-slate-100">
                      <td
                        className="py-2 pr-2 font-medium"
                        style={{ color: r.fill }}
                      >
                        {r.company}
                      </td>
                      <td className="py-2 pr-2 text-right tabular-nums">
                        {r.bn}
                      </td>
                      <td className="py-2 pr-2 text-right tabular-nums">
                        {fmtPct(r.sharePct)}
                      </td>
                      <td className="py-2 text-right tabular-nums">
                        {fmtPct(r.cumulativeSharePct)}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "raises" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Who captured the Aug???Q3 raises"
            subtitle={`Positive dollar raises sum to $${POSITIVE_RAISE_SLICES.reduce((s, r) => s + r.deltaBn, 0)}B; Amazon+Alphabet = ${fmtPct(HEADLINE.top2RaiseSharePct)}`}
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
